select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as arguments,pg_get_function_result(p.oid) as result,p.prosecdef as security_definer,p.provolatile as volatility,p.proconfig as config,p.prosrc as source from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e') order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid);
